package com.hau.ai.infrastructure.extraction;import com.hau.ai.application.port.out.TextExtractor;import com.hau.ai.domain.exception.*;import java.io.*;import java.nio.charset.StandardCharsets;import org.springframework.stereotype.Component;@Component public class PlainTextExtractor implements TextExtractor{public String extract(String type,InputStream data){if(!"text/plain".equals(type))throw new UnsupportedDocumentException("No extractor for "+type);try{return new String(data.readAllBytes(),StandardCharsets.UTF_8);}catch(IOException e){throw new DomainException("Extraction failed",e);}}}
